        _nova_main_ctx->_nova_parent_scope = NULL;
        _nova_main_ctx->_nova_init_snapshot = NULL;
        nova_fiber_spawn_into(&_nova_main_scope, _nova_main_fiber_entry, _nova_main_ctx);
